{
  "claims": [
    {
      "quote": "PALO ALTO, Cal. (July 2, 2015) – Theranos, Inc. (Theranos) today announced that it has received the U.S. Food and Drug Administration’s (FDA) clearance of its test system and test for herpes simplex 1 virus IgG.",
      "kind": "specific",
      "why": "This claim can be checked against the July 2, 2015 FDA clearance announcement for herpes simplex 1 virus IgG.",
      "summary": "Theranos announced on July 2, 2015, that it received FDA clearance for its HSV-1 IgG test."
    },
    {
      "quote": "Specifically, Theranos provided study data from 818 subjects of varying age and ethnicity, demonstrating that its system could be run accurately using only a finger stick as well as a traditional venous draw across large numbers of Theranos devices, all compared against an FDA cleared, commercially available reference method.",
      "kind": "specific",
      "why": "The number of 818 subjects can be verified against the study data submitted to the FDA.",
      "summary": "Theranos submitted study data from 818 subjects to demonstrate accuracy."
    },
    {
      "quote": "Theranos’ HSV-1 test costs $9.07 and is one of 153 tests Theranos makes available for less than $10.",
      "kind": "specific",
      "why": "The cost of $9.07 and the count of 153 tests can be checked against Theranos pricing records.",
      "summary": "The test costs $9.07, and 153 tests are available for under $10."
    },
    {
      "quote": "Theranos, Inc. is a consumer health technology company founded in 2003 by Elizabeth Holmes.",
      "kind": "specific",
      "why": "The founding year 2003 and founder Elizabeth Holmes can be checked against company registration records.",
      "summary": "Elizabeth Holmes founded the health technology company Theranos in 2003."
    },
    {
      "quote": "“We are proud to have received our first FDA clearance,” said Elizabeth Holmes, the founder and CEO of Theranos.",
      "kind": "specific",
      "why": "Elizabeth Holmes's quote can be verified as a statement made by the CEO of Theranos.",
      "summary": "Founder and CEO Elizabeth Holmes expressed pride in receiving the first FDA clearance."
    },
    {
      "quote": "Theranos offers lab tests in convenient locations in its Wellness Centers in Arizona and California, with plans to expand throughout the country.",
      "kind": "specific",
      "why": "The locations in Arizona and California can be checked against historical Wellness Center addresses.",
      "summary": "Theranos offers lab tests at Wellness Centers in Arizona and California with expansion plans."
    },
    {
      "quote": "Theranos is deeply committed to transparency in the laboratory testing space.",
      "kind": "vague",
      "why": "This statement is unverifiable puffery relying on the subjective claim of being deeply committed."
    }
  ]
}

